const crypto = require('crypto');

/**
 * Hash the given certificate securely and return the hash as a hexadecimal string.
 *
 * @param {string} cert - The certificate to be hashed.
 * @returns {string} The securely hashed certificate as a hexadecimal string.
 */
function hash_certificate(cert) {
    if (typeof cert !== 'string') {
        throw new TypeError('The certificate must be a string.');
    }

    // Further input sanitization
    const sanitizedCert = cert.replace(/[\0\x08\x09\x1a\n\r"'\\\%]/g, char => {
        switch (char) {
            case '\0':
                return '\\0';
            case '\x08':
                return '\\b';
            case '\x09':
                return '\\t';
            case '\x1a':
                return '\\z';
            case '\n':
                return '\\n';
            case '\r':
                return '\\r';
            case '"':
            case "'":
            case '\\':
            case '%':
                return '\\' + char; // Prepends a backslash to backslash, percent,
                                    // and double/single quotes
        }
    }).trim();

    const hash = crypto.createHash('sha256');
    hash.update(sanitizedCert);
    return hash.digest('hex');
}
